    pub open spec fn valid_storage_at_idx(&self, i: nat) -> bool {
        if self.is_checked_out(i) {
            !self.storage.dom().contains(i)
        } else {
            self.storage.dom().contains(i)

            && self.storage.index(i).id() == self.backing_cells.index(i as int)

            && if self.in_active_range(i) {
